def review(path,claim_id,scope,full=True):
    c=next(x for x in json.loads(path.read_text(encoding='utf-8-sig')) if x['claim_id']==claim_id)
    text_hash=hashlib.sha256(c['exact_statement'].encode()).hexdigest()
