    record={'reviewer':'account05/A094, B19','at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'verdict':'HOLDS_AT_STATED_SCOPE' if full else 'HOLDS_AT_SPECIFIED_CLAUSE_ONLY','scope':scope,'source':str(RUN/'AUDIT.md'),'source_claims_path':str(path),'source_claims_sha256':sha(path),'method':'independent all-parameter source-complete proof reconstruction and distinct integer-FWHT/Fraction/log-prime implementation','substantive_repair_supplied':False,'declared_statement_sha256':c['statement_sha256'],'computed_plain_statement_sha256':text_hash,'computed_canonical_statement_hypotheses_sha256':canonical,'declared_hash_matches_known_forms':c['statement_sha256'] in [text_hash,canonical],'hash_binding':'Original declared hash preserved; acceptance binds exact stored text, hypotheses, and source-file SHA256.'}
    c['review_records'].append(record)
    c['status']='INDEPENDENTLY_REVIEWED_AT_STATED_SCOPE_LOCALLY' if full else 'PARTIALLY_INDEPENDENTLY_REVIEWED_AT_EXPLICIT_SCOPE_LOCALLY'
    claims.append(c);hashrecords.append({k:record[k] for k in ['source_claims_path','declared_statement_sha256','computed_plain_statement_sha256','computed_canonical_statement_hypotheses_sha256','declared_hash_matches_known_forms']})
